{"cmd":"python - <<'PY'
import os, json, time, urllib.request, urllib.parse, urllib.error
base='https://usegalaxy.org'
history_id='bbd44e69cb8906b50bd7f88bcd513d75'
dataset_id='f9cad7b01a472135eef65ce2d701058a'
tool_id='toolshed.g2.bx.psu.edu/repos/iuc/kraken2/kraken2/2.17.1+galaxy0'
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()

def request(method, path, payload=None):
    data=None
    headers={'x-api-key': key}
    if payload is not None:
        data=json.dumps(payload).encode()
        headers['content-type']='application/json'
    req=urllib.request.Request(base+path, data=data, headers=headers, method=method)
    with urllib.request.urlopen(req, timeout=60) as r:
        raw=r.read().decode()
        return json.loads(raw) if raw else None

inputs={
  'single_paired': {
    'single_paired_selector': 'no',
    'input_sequences': {'src':'hda','id':dataset_id}
  },
  'use_names': True,
  'confidence': 0.0,
  'min_base_quality': 0,
  'minimum_hit_groups': 2,
  'quick': False,
  'split_reads': False,
  'report': {
    'create_report': 'true',
    'use_mpa_style': False,
    'report_zero_counts': False,
    'report_minimizer_data': True
  },
  'kraken2_database': '2025-02-05T204609Z_standard_prebuilt_core_nt_2024-09-04'
}
payload={'history_id': history_id, 'tool_id': tool_id, 'inputs': inputs, 'input_format':'21.01'}
try:
    result=request('POST','/api/tools',payload)
except urllib.error.HTTPError as e:
    print('SUBMIT_HTTP_ERROR', e.code)
    print(e.read().decode()[:3000])
    raise SystemExit(1)
print('SUBMITTED', json.dumps({k: result.get(k) for k in ['id','jobs','outputs']}, indent=2))
job_ids=[]
for j in result.get('jobs',[]):
    if isinstance(j, dict) and j.get('id'): job_ids.append(j['id'])
    elif isinstance(j, str): job_ids.append(j)
if not job_ids:
    print('NO_JOB_IDS', json.dumps(result)[:3000]); raise SystemExit(1)
terminal={'ok','error','deleted','deleted_new','upload','paused'}
while True:
    states=[]
    for jid in job_ids:
        job=request('GET','/api/jobs/'+urllib.parse.quote(jid, safe=''))
        states.append(job.get('state'))
    if all(s in terminal for s in states):
        print('JOB_STATES', states)
        break
    time.sleep(60)
# output details
outs=[]
for out in result.get('outputs',[]):
    oid=out.get('id') if isinstance(out,dict) else None
    if oid:
        ds=request('GET','/api/datasets/'+urllib.parse.quote(oid, safe=''))
        outs.append({'id': oid, 'name': ds.get('name'), 'state': ds.get('state'), 'extension': ds.get('extension'), 'file_size': ds.get('file_size')})
print('OUTPUTS', json.dumps(outs, indent=2))
# print stderr for errors only
if any(s!='ok' for s in states):
    for jid in job_ids:
        jd=request('GET','/api/jobs/'+urllib.parse.quote(jid, safe='')+'?full=true')
        print('JOB_DETAIL', json.dumps({k:jd.get(k) for k in ['id','state','tool_id','stderr','stdout']}, indent=2)[:5000])
    raise SystemExit(2)
PY","workdir":"/workspace","yield_time_ms":30000,"max_output_tokens":8000}

