query_id='f9cad7b01a4721351219da84ae9f69ba'
tid='toolshed.g2.bx.psu.edu/repos/devteam/ncbi_blast_plus/ncbi_blastn_wrapper/2.16.0+galaxy0'
with open(os.environ['GALAXY_API_KEY_FILE']) as f:key=f.read().strip()

def req(method,path,payload=None):
  data=None; headers={'x-api-key':key}
  if payload is not None:
    data=json.dumps(payload).encode(); headers['content-type']='application/json'
  r=urllib.request.Request(base+path, data=data, headers=headers, method=method)
  with urllib.request.urlopen(r, timeout=60) as resp:
    raw=resp.read().decode()
    return json.loads(raw) if raw else None
