 'evalue_cutoff': 1e-20,
 'output': {
   'out_format':'cols',
   'std_cols':['qseqid','sseqid','pident','length','evalue','bitscore'],
   'ext_cols':['qlen','slen'],
   'ids_cols':['saccver','stitle'],
   'misc_cols':['qcovhsp'],
   'tax_cols':['staxids','sscinames','scomnames']
 },
 'adv_opts': {
   'adv_opts_selector':'advanced',
   'filter_query': True,
   'strand':'-strand both',
   'max_hits':5,
   'max_hsps':1,
   'identity_cutoff':90,
   'word_size':None,
   'ungapped':False,
   'parse_deflines':False
 }
}
payload={'history_id':hid,'tool_id':tid,'inputs':inputs,'input_format':'21.01'}
try:
  res=req('POST','/api/tools',payload)
except Exception as e:
  print('SUBMIT_ERROR',type(e).__name__,e)
  if hasattr(e,'read'): print(e.read().decode()[:3000])
  sys.exit(1)
print('SUBMITTED', json.dumps({'jobs':res.get('jobs'),'outputs':res.get('outputs')}, indent=2)[:4000])
job_ids=[j['id'] if isinstance(j,dict) else j for j in res.get('jobs',[])]
terminal={'ok','error','deleted','deleted_new','paused'}
while True:
  states=[]
  for jid in job_ids:
    states.append(req('GET','/api/jobs/'+urllib.parse.quote(jid,safe='')).get('state'))
  if all(s in terminal for s in states):
    print('JOB_STATES',states); break
  time.sleep(60)
outs=[]
for out in res.get('outputs',[]):
  oid=out.get('id')
  if oid:
    ds=req('GET','/api/datasets/'+urllib.parse.quote(oid,safe=''))
    outs.append({'id':oid,'name':ds.get('name'),'state':ds.get('state'),'extension':ds.get('extension'),'file_size':ds.get('file_size')})
print('OUTPUTS', json.dumps(outs, indent=2))
if any(s!='ok' for s in states):
  for jid in job_ids:
    jd=req('GET','/api/jobs/'+urllib.parse.quote(jid,safe='')+'?full=true')
    print('JOB_DETAIL', json.dumps({k:jd.get(k) for k in ['id','state','stderr','stdout','tool_stderr','tool_stdout']}, indent=2)[:5000])
  sys.exit(2)
PY","workdir":"/workspace","yield_time_ms":30000,"max_output_tokens":10000}

