{"cmd":"python - <<'PY'
import urllib.request,re
for group,sp in [('fungi','saccharomyces_cerevisiae'),('plants','arabidopsis_thaliana')]:
 url=f'https://ftp.ensemblgenomes.ebi.ac.uk/pub/{group}/release-62/fasta/{sp}/cdna/'
 try:
  txt=urllib.request.urlopen(url,timeout=20).read().decode('utf-8','replace')
  print('\n',group,sp)
  for m in re.findall(r'href="([^"]+cdna\.all\.fa\.gz)"', txt): print(m)
 except Exception as e: print(group,sp,e)
PY","workdir":"/workspace","yield_time_ms":10000,"max_output_tokens":2000}

